def record_stamp(backend, kind, job_status="", refresh=True):
    """Read the backend's properties, save the snapshot if its stamp is new, compare it by value with the previous one
    (history 01's compare and other_changes), and append a row to stamps-t10.csv. (hw_t7.record_stamp.)"""
    STAMPS.mkdir(exist_ok=True)
    p = backend.properties(refresh=refresh)
    s = p.last_update_date.astimezone(timezone.utc)
    name = f"snapshot-{s.strftime('%Y%m%dT%H%M%SZ')}.json"
    path = STAMPS / name
    rows_p = HERE / "stamps-t10.csv"
    rows = list(csv.DictReader(rows_p.open())) if rows_p.exists() else []
    seen = [r["snapshot"] for r in rows]
    new = name not in seen
    row = {"utc": now(), "kind": kind, "stamp_utc": s.strftime("%Y-%m-%dT%H:%M:%SZ"), "stamp_raw": str(p.last_update_date),
           "new_stamp": new, "job_status": job_status, "snapshot": name}
    if not path.exists():
        path.write_text(json.dumps(p.to_dict(), default=str, indent=1) + "\n")
    if new and seen:
        prev = STAMPS / seen[-1]
        c = TH.compare(TH.load(prev), TH.load(path))
        o = TH.other_changes(prev, path)
        row.update({"q_T1": c["q_T1"], "q_T2": c["q_T2"], "q_readout_error": c["q_readout_error"], "g1_any": c["g1_any"],
                    "cz_error": c["cz_error"], "cz_length": c["cz_length"], "other_values_changed": o["other_values_changed"],
                    "any_value_changed": o["any_value_changed"]})
    row.update(published_summary(p))
    with rows_p.open("a", newline="") as fh:
        w = csv.DictWriter(fh, fieldnames=STAMP_FIELDS)
        if not rows:
            w.writeheader()
        w.writerow(row)
    return row


def qp(p, q, name, scale=1.0):
    try:
        v = p.qubit_property(q).get(name, (None,))[0]
        return None if v is None else round(float(v) * scale, 6)
    except Exception:
        return None


def published_summary(p):
    """The published readout error, T1 and T2 (us) of 7, 43 and 18 at this read, and the medians over every qubit."""
    n = len(p.qubits)
    ro = [qp(p, q, "readout_error") for q in range(n)]
    t1 = [qp(p, q, "T1", 1e6) for q in range(n)]
    t2 = [qp(p, q, "T2", 1e6) for q in range(n)]
    med = lambda a: None if not [x for x in a if x is not None] else round(float(np.median([x for x in a if x is not None])), 6)
    out = {"n_operational": sum(bool(p.is_qubit_operational(q)) for q in range(n)), "median_readout_error": med(ro),
           "median_T1_us": med(t1), "median_T2_us": med(t2)}
    for q in WATCH:
        out.update({f"q{q}_readout_error": ro[q], f"q{q}_T1_us": t1[q], f"q{q}_T2_us": t2[q]})
    return out


def published_per_qubit(p, qs):
    """Per qubit: the published readout error, P(1|0), P(0|1), T1 and T2 (us), and whether it is operational."""
    return {str(q): {"readout_error": qp(p, q, "readout_error"), "prob_meas1_prep0": qp(p, q, "prob_meas1_prep0"),
                     "prob_meas0_prep1": qp(p, q, "prob_meas0_prep1"), "T1_us": qp(p, q, "T1", 1e6), "T2_us": qp(p, q, "T2", 1e6),
                     "operational": bool(p.is_qubit_operational(q))} for q in qs}


def cycle_check(row, t=None):
    """t10-rule.md ("When", as test 7's rule): no job is submitted while the day's cycle is in progress, from a stamp at
    which T1 changed on more than half the qubits until 30 minutes after the next stamp at which CZ errors changed on
    more than half the edges. (hw_t7.cycle_check, unchanged in what it does.)"""
    t = t or datetime.now(timezone.utc)
    cyc = json.loads((HERE / "window-t10.json").read_text())["cycle"]
    out = {"utc": now(), "latest_T1_stamp_utc": cyc["latest_T1_stamp_utc"], "latest_CZ_stamp_utc": cyc["latest_CZ_stamp_utc"],
           "cycle_complete_in_48h": cyc["cycle_complete_in_48h"], "submissions_from_utc": cyc["submissions_from_utc"], "snapshot_read": row["snapshot"]}
    if not cyc["cycle_complete_in_48h"]:
        return {**out, "pass": False, "reason": "the walk's latest T1 stamp has no CZ stamp after it"}
    f = lambda s: datetime.fromisoformat(s.replace("Z", "+00:00"))
    if t < f(cyc["submissions_from_utc"]):
        return {**out, "pass": False, "reason": "less than 30 minutes after the latest CZ stamp"}
    cz_snap = HERE / "history-t10" / "snapshots" / f"snapshot-{f(cyc['latest_CZ_stamp_utc']).strftime('%Y%m%dT%H%M%SZ')}.json"
    c = TH.compare(TH.load(cz_snap), TH.load(STAMPS / row["snapshot"]))
    since = {"q_T1": c["q_T1"], "cz_error": c["cz_error"], "n_edges": c["n_edges"]}
    new_cycle = c["q_T1"] > TH.N_QUBITS / 2 or c["cz_error"] > c["n_edges"] / 2
    return {**out, "changed_since_latest_CZ_stamp": since, "new_cycle_since_walk": new_cycle, "pass": not new_cycle,
            "reason": "a new T1 or CZ step since the walk's latest CZ stamp" if new_cycle else "the day's cycle is complete and no new step has come"}


# --------------------------------------------------------------------------- the map and the sets
def undirected_edges(backend):
    """The coupling map's edges, an edge in either direction counted once."""
    return sorted({tuple(sorted((int(a), int(b)))) for a, b in backend.coupling_map.get_edges()})


def adjacency(edges, n):
    adj = {q: set() for q in range(n)}
    for a, b in edges:
        adj[a].add(b)
        adj[b].add(a)
    return adj


def take_set(order, eligible, adj):
    """t10-rule.md, the set by procedure: in this order, each qubit taken only if it is eligible and not adjacent to a
    qubit already taken."""
    taken = []
    for q in order:
        if q in eligible and not (adj[q] & set(taken)):
            taken.append(int(q))
    return taken


def independent(qs, adj):
    return all(not (adj[q] & set(qs)) for q in qs)


# --------------------------------------------------------------------------- the circuits
def wait_dt_of(t_us, backend):
    g = getattr(backend.target, "granularity", 1) or 1
    return W.even_wait(t_us * 1e-6 / backend.dt, g), g


def logical_ramsey(quad, wait_dt):
    """Test 7's one-qubit circuit (hw_t7.logical_ramsey): X, the package's Part B Ramsey on one qubit, H, the wait, H,
    measure; Y, the same with an S-dagger inserted right before the final H."""
    qc = W.part_b_circuit(1, wait_dt, "R")
    if quad == "Y":
        from qiskit.circuit import CircuitInstruction
        from qiskit.circuit.library import SdgGate
        k = max(i for i, x in enumerate(qc.data) if x.operation.name == "h")
        qc.data.insert(k, CircuitInstruction(SdgGate(), (qc.qubits[0],)))
        qc.name = f"Y{wait_dt}"
    return qc


def logical_readout(k):
    """Test 7's one-qubit readout circuits (hw_t7.readout_circuit's logical circuit): P10 measures, P01 applies X and
    then measures."""
    from qiskit import QuantumCircuit
    qc = QuantumCircuit(1, 1, name=k)
    if k == "P01":
        qc.x(0)
    qc.measure(0, 0)
    return qc


def on_set(one, qs, name):
    """The one-qubit logical circuit on every logical qubit k of an n-qubit circuit, its measure into classical bit k."""
    from qiskit import QuantumCircuit
    n = len(qs)
    qc = QuantumCircuit(n, n, name=name)
    for k in range(n):
        qc.compose(one, qubits=[k], clbits=[k], inplace=True)
    return qc


def build_set(qs, backend, waits=WAITS_US):
    """Job 1's design on the set qs at the waits given (job 1: 0 to 63 us; the scan: its eight): X and Y at each wait and
    the two readout circuits, each translated once onto sorted(qs) by manacitra.wait.to_backend."""
    qs = sorted(int(q) for q in qs)
    circ, info, ref = {}, {}, {}
    for t in waits:
        wdt, g = wait_dt_of(t, backend)
        for quad in QUADS:
            one = logical_ramsey(quad, wdt)
            circ[(quad, t)] = W.to_backend(on_set(one, qs, f"{quad}{wdt}-n{len(qs)}"), qs, backend)
            info[(quad, t)] = {"t_requested_us": t, "requested_dt": t * 1e-6 / backend.dt, "wait_dt": wdt, "granularity": g,
                               "logical_one_qubit": W.structure(one)}
            ref[(quad, t)] = one
    for k in READOUT:
        one = logical_readout(k)
        circ[(k, None)] = W.to_backend(on_set(one, qs, f"{k}-n{len(qs)}"), qs, backend)
        info[(k, None)] = {}
        ref[(k, None)] = one
    return circ, info, ref, qs


def build_survey(backend):
    entries = W.readout_survey(backend)
    return {(e["label"]["circuit"], None): e["circuit"] for e in entries}, list(range(backend.num_qubits))


def ops_of(c, q=None):
    """(name, physical qubits, clbits) per instruction, in order; with q, only those on qubit q (hw_61.ops_of)."""
    out = []
    for i in c.data:
        qs = [c.find_bit(x).index for x in i.qubits]
        if q is not None and q not in qs:
            continue
        out.append((i.operation.name, qs, [c.find_bit(x).index for x in i.clbits]))
    return out


def seq_of(c, q):
    """Qubit q's instructions in order, with an rz's angle in degrees (rounded to 1e-6) and a delay's length in dt."""
    out = []
    for i in c.data:
        if q not in [c.find_bit(x).index for x in i.qubits]:
            continue
        op = i.operation
        if op.name == "rz":
            out.append(("rz", round(math.degrees(float(op.params[0])), 6)))
        elif op.name == "delay":
            out.append(("delay", int(op.duration)))
        else:
            out.append((op.name, None))
    return out


def digest(c):
    """A hash of every instruction in order: name, qubits, clbits and parameters (hw_61.digest)."""
    def par(op):
        try:
            return [round(float(x), 12) for x in op.params]
        except Exception:
            return [str(x) for x in op.params]
    seq = [(i.operation.name, [c.find_bit(x).index for x in i.qubits], [c.find_bit(x).index for x in i.clbits], par(i.operation)) for i in c.data]
    return hashlib.sha256(json.dumps(seq).encode()).hexdigest()


def exact_p1_per_qubit(c, qs):
    """The exact noiseless P(1) of each qubit's own bit (hw_62.exact_p1_per_qubit): the circuits hold no instruction on
    two or more qubits (checked), so each qubit's outcome depends on its own instructions alone; each qubit's
    instructions, in order, are put on a one-qubit circuit and passed to manacitra.wait.exact_distribution (unchanged).
    (exact_distribution on the whole circuit would need a state over every qubit it acts on.)"""
    from qiskit import QuantumCircuit
    by_q = defaultdict(list)
    for i in c.data:
        qq = [c.find_bit(x).index for x in i.qubits]
        if len(qq) == 1:
            by_q[qq[0]].append(i)
    out = {}
    for q in qs:
        sub = QuantumCircuit(1, 1)
        for i in by_q[q]:
            sub.append(i.operation, [sub.qubits[0]], [sub.clbits[0]] if i.clbits else [])
        p = W.exact_distribution(sub)
        out[str(q)] = sum(v for key, v in p.items() if key[-1] == "1")
    return out


def scheduled_waits(c, qs, backend):
    """Per qubit, the wait as scheduled: the circuit scheduled by manacitra.wait.scheduled on the target, each qubit's
    own instructions timed (hw_50.timed) and its window from the end of its first sx to the start of its last
    (hw_50.window); with the delays the circuit itself holds on the qubit."""
    sch = W.scheduled(c, backend.target)
    ins = K50.instructions(sch)
    out = {}
    for q in qs:
        mine = [x for x in ins if x[1] == [q]]
        tl = K50.timed(mine, backend.target, backend.dt, [q])
        w = K50.window(tl, q)
        delays = [int(op.duration) for op, qq, _ in K50.instructions(c) if op.name == "delay" and qq == [q]]
        out[q] = {"T_dt": int(w["T_dt"]), "T_us": w["T_dt"] * backend.dt * 1e6, "n_sx": w["n_sx"], "delays_dt": delays}
    return out


def survey_checks(circ, qs, backend):
    """Kickoff 62's survey checks (hw_62.survey_checks, unchanged in what they check), on the package's survey
    circuits: S0 measures every qubit and has no gate; S1 has one X per qubit and the same measures; qubit i into
    clbit i; every measure at one time; exact P(1) 0 in S0 and 1 in S1 on every qubit; no swap; layout as named."""
    t, dt = backend.target, backend.dt
    rec = {}
    for (k, _), c in circ.items():
        ops = {a: int(b) for a, b in c.count_ops().items()}
        init = list(c.layout.initial_index_layout(filter_ancillas=True))
        allops = ops_of(c)
        touched = {q for _, qq, _ in allops for q in qq}
        r = {"count_ops": ops, "no_swap": ops.get("swap", 0) == 0, "layout_as_named": init == qs, "touches_named_qubits_only": touched == set(qs),
             "no_instruction_on_two_or_more_qubits": all(len(qq) == 1 for nm, qq, _ in allops if nm != "barrier")}
        tl = K50.timed(K50.instructions(W.scheduled(c, t)), t, dt, qs)
        meas = [(qq, cs, s) for _, nm, qq, cs, s, d in tl if nm == "measure"]
        m2c = {qq[0]: cs[0] for qq, cs, s in meas}
        r["n_measures"] = len(meas)
        r["measures_every_qubit"] = sorted(m2c) == qs and len(meas) == len(qs)
        r["qubit_i_into_clbit_i"] = all(m2c.get(q) == q for q in qs)
        r["measure_start_dt"] = sorted({s for *_, s in meas})
        r["all_measures_at_one_time"] = len(r["measure_start_dt"]) == 1
        gates = [(nm, qq) for nm, qq, _ in allops if nm not in ("measure", "delay", "barrier")]
        if k == "S0":
            r["no_gate"] = gates == []
        else:
            xs = sorted(qq[0] for nm, qq in gates if nm == "x")
            r["one_x_per_qubit"] = xs == qs and {nm for nm, _ in gates} == {"x"}
        p1 = exact_p1_per_qubit(c, qs)
        want = 0.0 if k == "S0" else 1.0
        r["exact_P1_expected"] = want
        r["exact_P1_min_max"] = [min(p1.values()), max(p1.values())]
        r["exact_P1_as_expected"] = all(abs(v - want) < 1e-9 for v in p1.values())
        rec[k] = r
    flat = [v for r in rec.values() for v in r.values() if isinstance(v, bool)]
    return rec, all(flat)


def set_checks(circ, info, ref, qs, edges, backend):
    """The rule's structural checks on one job's circuits (the docstring's list). Returns (records, waits, all pass)."""
    adj = adjacency(edges, backend.num_qubits)
    rank = {q: k for k, q in enumerate(qs)}
    shared = sorted([a, b] for a, b in edges if a in rank and b in rank)
    recs, ok = {"set": {"n_qubits": len(qs), "no_two_qubits_share_an_edge": not shared, "edges_inside_the_set": shared,
                        "independent_by_adjacency": independent(qs, adj)}}, not shared
    refseq_cache = {}
    for (k, t), c in circ.items():
        r = {}
        allops = ops_of(c)
        used = {q for _, qq, _ in allops for q in qq}
        r["every_instruction_on_the_set"] = used <= set(qs)
        r["every_qubit_of_the_set_used"] = used == set(qs)
        r["no_instruction_on_two_or_more_qubits"] = all(len(qq) == 1 for _, qq, _ in allops)
        meas = [(qq[0], cs[0]) for nm, qq, cs in allops if nm == "measure"]
        r["n_clbits_is_n"] = c.num_clbits == len(qs)
        r["each_qubit_measured_once_into_its_own_clbit"] = (len(meas) == len(qs) and sorted(q for q, _ in meas) == qs
                                                           and all(cb == rank[q] for q, cb in meas))
        if (k, t) not in refseq_cache:
            refseq_cache[(k, t)] = {q: seq_of(W.to_backend(ref[(k, t)], [q], backend), q) for q in qs}
        seqs = {q: seq_of(c, q) for q in qs}
        r["each_qubit_carries_test7s_sequence"] = all(seqs[q] == refseq_cache[(k, t)][q] for q in qs)
        p1 = exact_p1_per_qubit(c, qs)
        r["exact_P1_min_max"] = [min(p1.values()), max(p1.values())]
        if k in QUADS:
            i = info[(k, t)]
            names = {q: [nm for nm, _ in seqs[q] if nm != "delay"] for q in qs}
            r["X_names_rz_sx_rz_rz_sx_rz_measure"] = all(names[q] == ["rz", "sx", "rz", "rz", "sx", "rz", "measure"] for q in qs) if k == "X" else None
            if k == "Y":
                xs = {q: [s for s in seq_of(circ[("X", t)], q) if s[0] != "delay"] for q in qs}
                ys = {q: [s for s in seqs[q] if s[0] != "delay"] for q in qs}
                r["Y_is_X_with_one_rz_minus_90_before_the_last_H"] = all(ys[q] == xs[q][:3] + [("rz", -90.0)] + xs[q][3:] for q in qs)
            sw = scheduled_waits(c, qs, backend)
            i["scheduled"] = {str(q): v for q, v in sw.items()}
            r["delay_is_wait_dt_on_every_qubit"] = all(sw[q]["delays_dt"] == ([i["wait_dt"]] if i["wait_dt"] else []) for q in qs)
            r["scheduled_is_wait_dt_on_every_qubit"] = all(sw[q]["T_dt"] == i["wait_dt"] for q in qs)
            r["two_sx_on_every_qubit"] = all(sw[q]["n_sx"] == 2 for q in qs)
            r["wait_even"] = i["wait_dt"] % 2 == 0
            want = 0.0 if k == "X" else 0.5
        else:
            r["gates"] = sorted({nm for nm, _ in seqs[qs[0]] if nm not in ("delay", "barrier")})
            want = 0.0 if k == "P10" else 1.0
        r["exact_P1_expected"] = want
        r["exact_P1_as_expected_on_every_qubit"] = all(abs(v - want) < 1e-9 for v in p1.values())
        good = all(v for v in r.values() if isinstance(v, bool))
        r["pass"] = good
        ok = ok and good
        recs[f"{k}|{t}"] = r
    waits = [{"t_requested_us": t, "requested_dt": info[("X", t)]["requested_dt"], "wait_dt": info[("X", t)]["wait_dt"],
              "scheduled_dt": {q: sorted({v["T_dt"] for v in info[(q, t)]["scheduled"].values()}) for q in QUADS},
              "scheduled_us": {q: sorted({v["T_us"] for v in info[(q, t)]["scheduled"].values()}) for q in QUADS}} for t in sorted({t for (k, t) in info if k in QUADS})]
    for w in waits:
        w["difference_us"] = {q: [x - w["t_requested_us"] for x in w["scheduled_us"][q]] for q in QUADS}
        w["same_on_every_qubit"] = all(len(w["scheduled_dt"][q]) == 1 for q in QUADS)
    return recs, waits, ok


def label_of(job, set_name, qs, k, t, info, cp, dt):
