# --------------------------------------------------------------------------- test 10's own
def wait_of(q):
    return float(WAITS_US_OF.get(int(q), WAIT_DEFAULT_US))


def draw_sets_t10(eligible, edges, n):
    """t10-rule.md, the set by procedure: S with SEED_FIRST first (a seed already taken is skipped), then ascending; S'
    the same over the rest, no seeds."""
    adj = adjacency(edges, n)
    el = {int(q) for q in eligible}
    seen, order = set(), []
    for q in list(SEED_FIRST) + list(range(n)):
        if q not in seen:
            seen.add(q)
            order.append(q)
    s = take_set(order, el, adj)
    sp = take_set([q for q in range(n) if q not in s], el - set(s), adj)
    left = sorted(el - set(s) - set(sp))
    why = {str(q): {"neighbours_in_S": sorted(adj[q] & set(s)), "neighbours_in_S_prime": sorted(adj[q] & set(sp))} for q in left}
    seeds_left = {}
    for k, q in enumerate(SEED_FIRST):
        if q not in s:
            before = [x for x in SEED_FIRST[:k] if x in s]
            seeds_left[str(q)] = "not eligible" if q not in el else f"adjacent to {sorted(adj[q] & set(before))}, already in S at its turn"
    return {"S": s, "S_prime": sp, "eligible_in_neither": left, "why_left_out": why, "seeds_not_taken": seeds_left,
            "S_independent": independent(s, adj), "S_prime_independent": independent(sp, adj)}


def build_monitor(qs, backend):
    """The rule's four distinct circuits on the set: X and Y with each qubit at its own wait (test 7's one-qubit logical
    circuit at that qubit's wait_dt on its logical qubit, its measure into its own classical bit), and P10 and P01; each
    translated once onto sorted(qs) by manacitra.wait.to_backend."""
    from qiskit import QuantumCircuit
    qs = sorted(int(q) for q in qs)
    n = len(qs)
    wdt = {q: wait_dt_of(wait_of(q), backend)[0] for q in qs}
    circ, info, ref = {}, {}, {}
    for quad in QUADS:
        qc = QuantumCircuit(n, n, name=f"{quad}-monitor-n{n}")
        ones = {}
        for k, q in enumerate(qs):
            one = logical_ramsey(quad, wdt[q])
            qc.compose(one, qubits=[k], clbits=[k], inplace=True)
            ones[q] = one
        circ[quad] = W.to_backend(qc, qs, backend)
        info[quad] = {"wait_us_requested": {str(q): wait_of(q) for q in qs}, "wait_dt": {str(q): wdt[q] for q in qs}}
        ref[quad] = ones
    for k in READOUT:
        one = logical_readout(k)
        circ[k] = W.to_backend(on_set(one, qs, f"{k}-n{n}"), qs, backend)
        info[k] = {}
        ref[k] = {q: one for q in qs}
    return circ, info, ref, qs


def qubit_duration_dt(c, q, target, dt):
    """The sum of the durations of qubit q's instructions in c (hw_50.duration: a delay its own length, rz 0)."""
    return sum(K50.duration(op, qq, target, dt) for op, qq, _ in K50.instructions(c) if qq == [q])


def monitor_checks(circ, info, ref, qs, edges, backend):
    """The rule's structural checks on the four distinct circuits: every instruction on the set, none on two or more
    qubits; no two set qubits adjacent; each qubit measured once into its own bit; each qubit's instructions equal to
    test 7's one-qubit circuit at its own wait translated onto it alone (so each qubit carries exactly the two-H
    sequence, its only delay its own wait); each qubit's scheduled wait (end of its first sx to the start of its last)
    equal to its requested wait in dt; the circuit's duration (QuantumCircuit.estimate_duration on the target) equal to
    the longest qubit sequence, the qubit with the longest wait; the exact noiseless P(1) per qubit 0, 0.5, 0 and 1."""
    t, dt = backend.target, backend.dt
    adj = adjacency(edges, backend.num_qubits)
    rank = {q: k for k, q in enumerate(qs)}
    shared = sorted([a, b] for a, b in edges if a in rank and b in rank)
    recs, ok = {"set": {"n_qubits": len(qs), "no_two_qubits_share_an_edge": not shared, "edges_inside_the_set": shared,
                        "independent_by_adjacency": independent(qs, adj)}}, not shared
    waits = {}
    for k, c in circ.items():
        r = {}
        allops = ops_of(c)
        used = {q for _, qq, _ in allops for q in qq}
        r["every_instruction_on_the_set"] = used <= set(qs)
        r["every_qubit_of_the_set_used"] = used == set(qs)
        r["no_instruction_on_two_or_more_qubits"] = all(len(qq) == 1 for _, qq, _ in allops)
        meas = [(qq[0], cs[0]) for nm, qq, cs in allops if nm == "measure"]
        r["n_clbits_is_n"] = c.num_clbits == len(qs)
        r["each_qubit_measured_once_into_its_own_clbit"] = (len(meas) == len(qs) and sorted(q for q, _ in meas) == qs and all(cb == rank[q] for q, cb in meas))
        seqs = {q: seq_of(c, q) for q in qs}
        r["each_qubit_carries_test7s_sequence_at_its_own_wait"] = all(seqs[q] == seq_of(W.to_backend(ref[k][q], [q], backend), q) for q in qs)
        p1 = exact_p1_per_qubit(c, qs)
        r["exact_P1_min_max"] = [min(p1.values()), max(p1.values())]
        if k in QUADS:
            sw = scheduled_waits(c, qs, backend)
            wd = info[k]["wait_dt"]
            r["delay_is_its_own_wait_on_every_qubit"] = all(sw[q]["delays_dt"] == ([wd[str(q)]] if wd[str(q)] else []) for q in qs)
            r["scheduled_wait_equals_requested_on_every_qubit"] = all(sw[q]["T_dt"] == wd[str(q)] for q in qs)
            r["two_sx_on_every_qubit"] = all(sw[q]["n_sx"] == 2 for q in qs)
            r["every_wait_even"] = all(wd[str(q)] % 2 == 0 for q in qs)
            qd = {q: qubit_duration_dt(c, q, t, dt) for q in qs}
            longest = max(qs, key=lambda q: (wd[str(q)], q))
            est = int(round(c.estimate_duration(t, unit="dt")))
            r["circuit_duration_dt"] = est
            r["longest_wait_qubit"] = longest
            r["circuit_duration_is_the_longest_wait_qubits_sequence"] = est == qd[longest] == max(qd.values())
            waits[k] = {str(q): {"requested_us": wait_of(q), "wait_dt": wd[str(q)], "scheduled_dt": sw[q]["T_dt"], "scheduled_us": sw[q]["T_us"],
                                 "difference_us": sw[q]["T_us"] - wait_of(q)} for q in qs}
            want = 0.0 if k == "X" else 0.5
        else:
            want = 0.0 if k == "P10" else 1.0
        r["exact_P1_expected"] = want
        r["exact_P1_as_expected_on_every_qubit"] = all(abs(v - want) < 1e-9 for v in p1.values())
        good = all(v for v in r.values() if isinstance(v, bool))
        r["pass"] = good
        ok = ok and good
        recs[k] = r
    return recs, waits, ok


def monitor_order():
    """The rule's 300 positions: (circuit, repeat or None, block)."""
    out = [(k, None, "start") for k in READOUT]
    for r in range(1, N_REP + 1):
        out += [("X", r, "monitor"), ("Y", r, "monitor")]
    return out + [(k, None, "end") for k in READOUT]


def assemble_monitor(job, set_name, qs, circ, info, dt):
    circs, labels, shots = [], [], []
    for pos, (k, r, block) in enumerate(monitor_order()):
        circs.append(circ[k])
        lab = {"job": job, "set": set_name, "position": pos, "block": block, "repeat": r, "circuit": k, "quadrature": k if k in QUADS else None,
               "n_qubits": len(qs), "clbits": "the set's qubits in ascending index, the k-th into clbit k",
               "waits": "each qubit its own; see the job's waits record" if k in QUADS else None}
        labels.append(lab)
        shots.append(SHOTS_JOB)
    return circs, labels, shots


def monitor_order_checks(circ, circs, labels, shots):
    order = monitor_order()
    dig = {k: digest(c) for k, c in circ.items()}
    pos_dig = [digest(c) for c in circs]
    r = {"n_positions": len(circs), "n_positions_is_300": len(circs) == N_POSITIONS_JOB,
         "labels_in_the_rules_order": [(l["circuit"], l["repeat"], l["block"]) for l in labels] == [tuple(x) for x in order],
         "positions_numbered_in_order": [l["position"] for l in labels] == list(range(len(labels))),
         "each_position_carries_its_labels_circuit": pos_dig == [dig[k] for k, rr, b in order],
         "every_repeat_X_then_Y": all(labels[2 + 2 * (k - 1)]["circuit"] == "X" and labels[3 + 2 * (k - 1)]["circuit"] == "Y" for k in range(1, N_REP + 1)),
         "readout_first_and_last": [l["circuit"] for l in labels[:2]] == list(READOUT) and [l["circuit"] for l in labels[-2:]] == list(READOUT),
         "one_shot_count": set(shots) == {SHOTS_JOB}, "shots_total": sum(shots),
         "note": "each distinct circuit is translated once before the list is made; the sampler is given the list as (circuit, None, shots) in this order"}
    r["pass"] = all(v for v in r.values() if isinstance(v, bool))
    return r


def built_monitor(b, job, set_name, qs, edges):
    circ, info, ref, qs = build_monitor(qs, b)
    recs, waits, ok = monitor_checks(circ, info, ref, qs, edges, b)
    circs, labels, shots = assemble_monitor(job, set_name, qs, circ, info, b.dt)
    order = monitor_order_checks(circ, circs, labels, shots)
    lim = limits(b, circs, shots)
    ok = ok and order["pass"] and lim["within"] and not lim["instructions_not_in_target"]
    return circ, info, recs, circs, labels, shots, lim, waits, ok, qs, order

