"""Test 10: the per-qubit analysis of every job (phase_t10.py, unchanged), the pooled verdicts and the dwell-time
words, and every item t10-rule.md reports beside the verdicts. Written before any job's counts existed (17 October 2026,
in the dry run). Choices the rule leaves open, fixed here:
  - each qubit's classical bit is its rank in the set sorted by ascending index; a position's count of 1 on that bit is
    read with bit 0 rightmost;
  - the spans come from the counts file's execution_metadata (saved at the fetch); if absent, the job's result is
    retrieved again, read-only, before the analysis (--retrieve, hw_t10's service and spans_record), and that is
    recorded;
  - every position must have run in exactly one span with all its shots, as in tests 7 to 9's records; the rule does
    not cover a position whose shots ran in two spans, so if one does the analysis stops and the record says so, for
    the author to rule on;
  - item 2, the boundary table: for each boundary between spans consecutive in start order, the pair of repeats that
    ran last in the earlier span and first in the later (their wrapped phase difference and its standard error,
    sqrt(s_k^2 + s_(k+1)^2)); the within-span control for each span: the pair at the span's middle, (m, m + 1) with m
    the middle one of the span's included repeats; the counts of usable qubits whose difference exceeds 5 standard
    errors across each;
  - item 3, the levels' separation of an antiphase qubit: the wrapped difference of its two most populated levels;
  - item 4, the monitors' frequency reading: each level's phase minus the job's weighted mean phase, times 1 / (2 pi t)
    (7.96 kHz per rad at 20 us, the rule's 8.0); each switch's size in kHz the same way;
  - item 5, the two jobs on S: the last included repeat of job 1 against the first of job 2, the wrapped difference
    and its standard error.
Usage: python -B analyse_t10.py --counts1 F1 [--counts2 F2] [--counts3 F3] --survey SV --sets SETS [--out fits-t10.json]
       [--retrieve]"""
from __future__ import annotations

import argparse
import hashlib
import json
import math
import sys
import time
from collections import defaultdict
from datetime import datetime
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
import phase_t10 as P  # noqa: E402

RULE_SHA = "89633a8d496eb7a9344c8c20187e0283fa0be69fe650b5b7b08bafdae96e8013"
ANTIPHASE = (43, 11, 120, 134)
N_SE = 5.0


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def spans_of(rec, retrieve):
    ex = rec.get("execution_metadata") or {}
    note = "saved with the counts at the fetch"
    if not ex.get("present"):
        if not retrieve:
            sys.exit(f"STOP: job {rec.get('job')} has no saved execution record; rerun with --retrieve")
        import hw_t10 as H
        res = H.service().job(rec["job_id"]).result()
        ex = H.spans_record(res)
        note = "retrieved again before the analysis (it was not saved at the fetch)"
    out = []
    for s in ex["execution_spans"]:
        out.append({"span": s["span"], "positions": s["positions"], "start": datetime.fromisoformat(s["start_utc"]), "stop": datetime.fromisoformat(s["stop_utc"]),
                    "duration_s": s["duration_s"], "start_utc": s["start_utc"], "stop_utc": s["stop_utc"], "size_shots": s.get("size_shots")})
    whole = whole_positions(ex, rec)
    if not whole["every_position_in_exactly_one_span_with_all_its_shots"]:
        sys.exit(f"STOP: job {rec.get('job')}: a position's shots ran in more than one span, or in none ({whole}); the rule does not cover this; the author rules")
    return out, ex, note


def whole_positions(ex, rec):
    """Every position in exactly one span, with all its shots in that span (as in tests 7 to 9's records)."""
    seen = defaultdict(list)
    for s in ex["execution_spans"]:
        spp = s.get("shots_per_position") or {}
        for p in s["positions"]:
            seen[int(p)].append((s["span"], spp.get(str(p))))
    n, shots = len(rec["labels"]), rec["shots"]
    bad = {p: v for p, v in seen.items() if len(v) != 1 or v[0][1] != shots[p]}
    missing = [p for p in range(n) if p not in seen]
    return {"every_position_in_exactly_one_span_with_all_its_shots": not bad and not missing, "positions_split_or_short": {str(p): v for p, v in sorted(bad.items())[:20]},
            "positions_in_no_span": missing[:20]}


def ones_per_qubit(rec):
    qs = sorted(int(q) for q in rec["qubits"])
    n = len(qs)
    ones = np.zeros((len(rec["counts"]), n), np.int64)
    for k, cts in enumerate(rec["counts"]):
        tot = 0
        for key, m in cts.items():
            b = np.frombuffer(key.replace(" ", "")[::-1].encode(), dtype=np.uint8).astype(np.int64) - 48
            if len(b) != n:
                sys.exit(f"STOP: position {k} has a key of {len(b)} bits, not {n}")
            ones[k] += b * m
            tot += m
        if tot != rec["shots"][k]:
            sys.exit(f"STOP: position {k} returned {tot} shots")
    return qs, ones


def wait_of(rec, q):
    w = rec.get("waits") or {}
    x = (w.get("X") or {}).get(str(q))
    return float(x["requested_us"]) if x else None


def job_record(spans):
    order = sorted(spans, key=lambda s: s["start"])
    gaps = [(b["start"] - a["stop"]).total_seconds() for a, b in zip(order, order[1:])]
    return {"spans": [{"span": s["span"], "start_utc": s["start_utc"], "stop_utc": s["stop_utc"], "duration_s": s["duration_s"], "size_shots": s["size_shots"],
                       "n_positions": len(s["positions"]), "position_runs": runs(s["positions"])} for s in order], "gaps_s": gaps}


def runs(idx):
    out = []
    for i in sorted(idx):
        if out and i == out[-1][1] + 1:
            out[-1][1] = i
        else:
            out.append([i, i])
    return out


def analyse_job(path, sv, retrieve):
    rec = json.loads(Path(path).read_text())
    spans, ex, note = spans_of(rec, retrieve)
    qs, ones = ones_per_qubit(rec)
    labels = rec["labels"]
    out = {}
    for j, q in enumerate(qs):
        e0 = sv["qubits"].get(str(q), {}).get("e")
        out[str(q)] = P.analyse(ones[:, j], labels, spans, wait_of(rec, q), e_job0=e0, shots=rec["shots"][0])
        ro = {}
        for k, lab in enumerate(labels):
            if lab["circuit"] in ("P10", "P01"):
                ro[f"{lab['circuit']}_{lab['block']}"] = ones[k, j] / rec["shots"][k]
        out[str(q)]["readout_in_job"] = {**{k: float(v) for k, v in ro.items()},
                                        "e_start": (ro["P10_start"] + 1 - ro["P01_start"]) / 2, "e_end": (ro["P10_end"] + 1 - ro["P01_end"]) / 2,
                                        "e_job0": e0, "published": sv["qubits"].get(str(q), {}).get("published", {}).get("readout_error")}
    usable = [r for r in out.values() if r["usable"]]
    count = {v: sum(1 for r in usable if r["verdict"] == v) for v in ("QUIET", "SWITCHES AT BOUNDARIES ONLY", "SWITCHES WITHIN SPANS")}
    count["NOT USABLE"] = len(out) - len(usable)
    return {"job": rec.get("job"), "job_id": rec.get("job_id"), "set": rec.get("set"), "qubits": qs, "spans_source": note, "execution_record": job_record(spans),
            "count": count, "per_qubit": out, "counts_sha256": sha(path)}


def boundary_table(job):
    """Item 2: per usable qubit, the difference across each boundary; the counts beside the within-span control."""
    per, n_b, n_c = {}, {}, {}
    for q, r in job["per_qubit"].items():
        if not r["usable"]:
            continue
        reps = [x for x in r["repeats"] if not x["straddles"]]
        spans_order = []
        for x in reps:
            if not spans_order or spans_order[-1] != x["span"]:
                spans_order.append(x["span"])
        rows = []
        for a, b in zip(reps, reps[1:]):
            if a["span"] != b["span"]:
                d = P.wrap(b["theta"] - a["theta"])
                se = math.sqrt(a["s"] ** 2 + b["s"] ** 2)
                rows.append({"between_spans": [a["span"], b["span"]], "k": a["k"], "k1": b["k"], "d": d, "se": se, "over_5_se": abs(d) > N_SE * se})
        ctrl = []
        for sp in dict.fromkeys(x["span"] for x in reps):
            xs = [x for x in reps if x["span"] == sp]
            if len(xs) >= 2:
                m = len(xs) // 2 - 1
                a, b = xs[m], xs[m + 1]
                d = P.wrap(b["theta"] - a["theta"])
                se = math.sqrt(a["s"] ** 2 + b["s"] ** 2)
                ctrl.append({"span": sp, "k": a["k"], "k1": b["k"], "d": d, "se": se, "over_5_se": abs(d) > N_SE * se})
        per[q] = {"boundaries": rows, "control": ctrl}
        for i, x in enumerate(rows):
            n_b[str(i)] = n_b.get(str(i), 0) + int(x["over_5_se"])
        for i, x in enumerate(ctrl):
            n_c[str(i)] = n_c.get(str(i), 0) + int(x["over_5_se"])
    return {"per_qubit": per, "n_over_5_se_at_each_boundary": n_b, "n_over_5_se_at_each_within_span_control": n_c,
            "n_usable": sum(1 for r in job["per_qubit"].values() if r["usable"])}


def antiphase(job):
    out = {}
    for q in ANTIPHASE:
        r = job["per_qubit"].get(str(q))
        if not r:
            continue
        lv = r["levels"]
        sep = abs(P.wrap(lv[0]["mean"] - lv[1]["mean"])) if len(lv) >= 2 else None
        out[str(q)] = {"wait_us": r["wait_us"], "verdict": r["verdict"], "theta": [x["theta"] for x in r["repeats"]], "r": [x["r"] for x in r["repeats"]],
                       "levels": [{"mean": L["mean"], "se": L["se"], "n_repeats": L["n_repeats"]} for L in lv], "separation_rad": sep,
                       "within_0.3_of_pi": None if sep is None else abs(sep - math.pi) <= 0.3}
    return out


def monitors(job):
    out = {}
    for q, r in job["per_qubit"].items():
        if r["wait_us"] != 20.0 or not r["usable"]:
            continue
        m = r["job_mean_phase"]
        out[q] = {"levels_kHz_from_job_mean": [P.wrap(L["mean"] - m) * r["kHz_per_rad"] for L in r["levels"]],
                  "switch_sizes_kHz": [x["size_kHz"] for x in r["switches"]], "kHz_per_rad": r["kHz_per_rad"]}
    return out


def two_jobs(j1, j2):
    out = {}
    for q in j1["per_qubit"]:
        a, b = j1["per_qubit"][q], (j2["per_qubit"].get(q) if j2 else None)
        if b is None:
            continue
        la = [x for x in a["repeats"] if not x["straddles"]][-1]
        fb = [x for x in b["repeats"] if not x["straddles"]][0]
        d = P.wrap(fb["theta"] - la["theta"])
        se = math.sqrt(la["s"] ** 2 + fb["s"] ** 2)
        out[q] = {"job1": a["verdict"], "job2": b["verdict"], "levels_job1": [L["mean"] for L in a["levels"]], "levels_job2": [L["mean"] for L in b["levels"]],
                  "end_of_job1_to_start_of_job2": {"d": d, "se": se, "over_5_se": abs(d) > N_SE * se}}
    return out


def lean(job):
    """The per-qubit record without its per-pair list (which stays in the full file)."""
    return {q: {k: v for k, v in r.items() if k != "pairs"} for q, r in job["per_qubit"].items()}

