"""Test 10: the report's tables, from the analysis record (analyse_t10.py's fits file), the sets and the jobs' check
records. Formatting only: every number is read from those files, none is computed anew except unit conversions named in
the headers (rad to kHz at the qubit's wait, 1 / (2 pi t)) and the rounding. Written before the live analysis ran and
tried on the dry run's simulated record. Writes PREFIX-*.md.

Usage: python -B tables_t10.py --fits F --sets SETS [--checks C1 C2 C3] [--prefix tables-t10]"""
from __future__ import annotations

import argparse
import gzip
import json
import math
from pathlib import Path

HERE = Path(__file__).resolve().parent
ANTIPHASE = ("43", "11", "120", "134")


def load(p):
    b = Path(p).read_bytes()
    return json.loads(gzip.decompress(b) if p.endswith(".gz") else b)


def f(x, n=3):
    if x is None:
        return ""
    if isinstance(x, float) and (math.isinf(x) or math.isnan(x)):
        return str(x)
    return f"{x:.{n}f}" if isinstance(x, float) else str(x)


def ci(r):
    lo, hi = r["within_rate_ci90_per_s"]
    return f"{f(r['within_rate_per_s'], 4)} ({f(lo, 4)} to {f(hi, 4)})" if r["within_rate_per_s"] is not None else ""


def counts(F):
    rows = ["| job | set | QUIET | SWITCHES AT BOUNDARIES ONLY | SWITCHES WITHIN SPANS | NOT USABLE |", "|---|---|---|---|---|---|"]
    for j, c in F["count_by_job"].items():
        rows.append(f"| {j} | {F['jobs'][j]['set']} ({len(F['jobs'][j]['qubits'])} qubits) | {c['QUIET']} | {c['SWITCHES AT BOUNDARIES ONLY']} | {c['SWITCHES WITHIN SPANS']} | {c['NOT USABLE']} |")
    c = F["count_pooled_S"]
    rows.append(f"| pooled, jobs 1 and 2 | S | {c['QUIET']} | {c['SWITCHES AT BOUNDARIES ONLY']} | {c['SWITCHES WITHIN SPANS']} | {c['NOT USABLE']} |")
    return "\n".join(rows)


def switches(F):
    out = ["| job | qubit | wait (µs) | verdict | n_within | n_boundary | within-span rate per s (90%) | levels (rad) | switches: pair, kind, size rad (kHz) |",
           "|---|---|---|---|---|---|---|---|---|"]
    for j, job in F["jobs"].items():
        for q, r in sorted(job["per_qubit"].items(), key=lambda x: int(x[0])):
            if not r["verdict"].startswith("SWITCHES"):
                continue
            lv = ", ".join(f"{L['mean']:+.3f} ({L['n_repeats']})" for L in r["levels"])
            sw = "; ".join(f"({s['k']}, {s['k1']}) {s['kind']} {s['d']:+.3f} ({s['size_kHz']:+.2f})" for s in r["switches"])
            out.append(f"| {j} | {q} | {f(r['wait_us'], 0)} | {r['verdict']} | {r['n_within']} | {r['n_boundary']} | {ci(r)} | {lv} | {sw} |")
    dw = ["| qubit | n_within pooled | dwell times | mean (s) | sd over mean | Kolmogorov p | word |", "|---|---|---|---|---|---|---|"]
    for q, d in sorted(F["dwell"].items(), key=lambda x: (x[0].startswith("S_prime"), int(x[0].split("_")[-1]))):
        if d["n_within_pooled"] == 0:
            continue
        dw.append(f"| {q} | {d['n_within_pooled']} | {', '.join(f'{x:.2f}' for x in d['dwell_s'])} | {f(d.get('mean_s'), 2)} | {f(d.get('sd_over_mean'), 3)} | "
                  f"{f(d.get('ks_p'), 3)} | {d['word'] or 'none (fewer than 8 within-span switches, or fewer than 2 dwell times)'} |")
    if len(out) == 2:
        out = ["No qubit returned SWITCHES in any job."]
    if len(dw) == 2:
        dw = ["None: no qubit has a within-span switch, so no dwell time and no dwell-time word."]
    return "\n".join(out) + "\n\nLevels: each level's weighted mean phase in rad, with its number of repeats.\n\n**Dwell times, every qubit with a within-span switch:**\n\n" + "\n".join(dw)


def per_job(F, j):
    job = F["jobs"][j]
    rows = ["| qubit | wait (µs) | verdict | median r | e, job 0 | n_within | n_boundary | rate per s (90%) | levels | slope per span (kHz per minute) |",
            "|---|---|---|---|---|---|---|---|---|---|"]
    for q, r in sorted(job["per_qubit"].items(), key=lambda x: int(x[0])):
        sl = ", ".join(f"{v['kHz_per_minute']:+.2f}" if v and v.get("kHz_per_minute") is not None else "" for v in r["slopes"].values())
        rows.append(f"| {q} | {f(r['wait_us'], 0)} | {r['verdict']} | {f(r['usable_reasons']['median_r'])} | {f(r['usable_reasons']['e_job0'], 4)} | {r['n_within']} | "
                    f"{r['n_boundary']} | {ci(r)} | {r['n_levels']} | {sl} |")
    return "\n".join(rows)


def execution(F):
    out = []
    for j, job in F["jobs"].items():
        ex = job["execution_record"]
        any_q = next(iter(job["per_qubit"].values()))
        out.append(f"**Job {j}** ({job['job_id']}; spans {job['spans_source']}):\n")
        out += ["| span | start (UTC) | stop (UTC) | duration (s) | positions | shots | repeats assigned | repeat period (s) |", "|---|---|---|---|---|---|---|---|"]
        for s in ex["spans"]:
            runs = ", ".join(f"{a} to {b}" for a, b in s["position_runs"])
            out.append(f"| {s['span']} | {s['start_utc']} | {s['stop_utc']} | {f(s['duration_s'], 3)} | {runs} | {s['size_shots']} | "
                       f"{any_q['repeats_per_span'].get(str(s['span']))} | {f(any_q['repeat_period_s'].get(str(s['span'])), 4)} |")
        out.append(f"\nGaps between spans (s): {', '.join(f(g, 3) for g in ex['gaps_s'])}. Straddling repeats: {F['beside']['1_straddling_repeats'][j] or 'none'}.\n")
    return "\n".join(out)


def boundary(F):
    out = []
    for j, b in F["beside"]["2_boundary_table"].items():
        nb, nc = b["n_over_5_se_at_each_boundary"], b["n_over_5_se_at_each_within_span_control"]
        out.append(f"**Job {j}:** {b['n_usable']} usable qubits. Over 5 standard errors at each boundary: "
                   + "; ".join(f"boundary {k}: {v}" for k, v in nb.items()) + ". At each span's middle pair (the control): "
                   + "; ".join(f"span {k}: {v}" for k, v in nc.items()) + ".\n")
        first = next(iter(b["per_qubit"].values()))
        hb = " | ".join(f"boundary ({x['k']}, {x['k1']})" for x in first["boundaries"])
        hc = " | ".join(f"control span {x['span']} ({x['k']}, {x['k1']})" for x in first["control"])
        out += [f"| qubit | {hb} | {hc} |", "|---|" + "---|" * (len(first["boundaries"]) + len(first["control"]))]
        for q, v in sorted(b["per_qubit"].items(), key=lambda x: int(x[0])):
            cells = [f"{x['d']:+.3f} ± {x['se']:.3f}{' **over 5 SE**' if x['over_5_se'] else ''}" for x in v["boundaries"] + v["control"]]
            out.append(f"| {q} | " + " | ".join(cells) + " |")
        out.append("")
    return "\n".join(out)


def antiphase(F):
    out = ["| job | qubit | wait (µs) | verdict | levels: mean rad (se, repeats) | separation (rad) | within 0.3 rad of π |", "|---|---|---|---|---|---|---|"]
    series = []
    for j, a in F["beside"]["3_antiphase"].items():
        for q in ANTIPHASE:
            if q not in a:
                continue
            x = a[q]
            lv = "; ".join(f"{L['mean']:+.3f} ({L['se']:.3f}, {L['n_repeats']})" for L in x["levels"])
            w = "" if x["within_0.3_of_pi"] is None else ("yes" if x["within_0.3_of_pi"] else "no")
            out.append(f"| {j} | {q} | {f(x['wait_us'], 0)} | {x['verdict']} | {lv} | {f(x['separation_rad'])} | {w} |")
            series.append(f"**Job {j}, qubit {q}, θ_k (rad), k = 1 to 148:** " + " ".join(f"{t:+.2f}" for t in x["theta"]))
            series.append(f"**Job {j}, qubit {q}, r_k:** " + " ".join(f"{t:.3f}" for t in x["r"]))
    return "\n".join(out) + "\n\n" + "\n\n".join(series)


def monitors(F):
    out = []
    for j, m in F["beside"]["4_monitors"].items():
        one = [q for q, v in m.items() if len(v["levels_kHz_from_job_mean"]) == 1 and not v["switch_sizes_kHz"]]
        if len(one) == len(m):
            out.append(f"**Job {j}:** {len(m)} usable qubits at 20 µs, every one with one level and no switch.\n")
            continue
        out.append(f"**Job {j}:** {len(m)} usable qubits at 20 µs; {len(one)} with one level and no switch. The others:\n")
        out += ["| qubit | levels, kHz from the job's mean | switch sizes (kHz) |", "|---|---|---|"]
        for q, v in sorted(m.items(), key=lambda x: int(x[0])):
            if q in one:
                continue
            out.append(f"| {q} | {', '.join(f'{x:+.2f}' for x in v['levels_kHz_from_job_mean'])} | {', '.join(f'{x:+.2f}' for x in v['switch_sizes_kHz'])} |")
        out.append("")
    return "\n".join(out)


def two_jobs(F):
    t = F["beside"]["5_two_jobs_on_S"]
    if not t:
        return "Job 2 did not run."
    out = ["| qubit | job 1 | job 2 | levels job 1 (rad) | levels job 2 (rad) | end of job 1 to start of job 2 (rad) | over 5 SE |", "|---|---|---|---|---|---|---|"]
    for q, v in sorted(t.items(), key=lambda x: int(x[0])):
        e = v.get("end_of_job1_to_start_of_job2") or {}
        out.append(f"| {q} | {v['job1']} | {v['job2']} | {', '.join(f'{x:+.3f}' for x in v['levels_job1'])} | {', '.join(f'{x:+.3f}' for x in v['levels_job2'])} | "
                   f"{f(e.get('d'))} ± {f(e.get('se'))} | {'yes' if e.get('over_5_se') else 'no'} |")
    return "\n".join(out)


def readout(F):
    ro = F["beside"]["6_readout"]
    jobs = list(ro)
    qs = sorted({q for j in jobs for q in ro[j]}, key=int)
    head = "| qubit | e, job 0 | published | " + " | ".join(f"job {j} start | job {j} end" for j in jobs) + " |"
    out = [head, "|---|---|---|" + "---|---|" * len(jobs)]
    for q in qs:
        any_ = next(ro[j][q] for j in jobs if q in ro[j])
        cells = []
        for j in jobs:
            x = ro[j].get(q)
            cells += [f(x["e_start"], 4), f(x["e_end"], 4)] if x else ["", ""]
        out.append(f"| {q} | {f(any_['e_job0'], 4)} | {f(any_['published'], 4)} | " + " | ".join(cells) + " |")
    return "\n".join(out)


def sets(S, checks):
    out = [f"**S, {len(S['S'])} qubits, in the order taken:** {', '.join(map(str, S['S']))}.", "",
           f"**S′, {len(S['S_prime'])} qubits:** {', '.join(map(str, S['S_prime']))}.", "",
           f"**Eligible in neither, {len(S['eligible_in_neither'])}:** {', '.join(map(str, S['eligible_in_neither']))}.", "",
           f"**Seeds not taken:** {json.dumps(S['seeds_not_taken'])}.", ""]
    for j, c in checks.items():
        w = c["waits"]
        diff = max(abs(v["difference_us"]) for k in ("X", "Y") for v in w[k].values())
        by = {}
        for q, v in w["X"].items():
            by.setdefault((v["requested_us"], v["scheduled_us"]), []).append(int(q))
        rows = "; ".join(f"{len(v)} qubit{'s' if len(v) != 1 else ''} requested {a} µs, scheduled {b} µs" + (f" ({', '.join(map(str, sorted(v)))})" if len(v) <= 4 else "")
                         for (a, b), v in sorted(by.items()))
        out.append(f"**Job {j}'s waits:** {rows}. The largest difference between requested and scheduled, over X and Y and every qubit: {diff} µs.")
    return "\n".join(out)
